export interface HdsFilterBarFilterGroupCheckboxSignature {
  Args: {
    value: string;
    label: string;
    name: string;
    searchValue?: string;
    keyFilter?: HdsFilterBarFilter;
    onChange?: (event: Event, label?: string) => void;
  };
  Blocks: {
    default: [];
  };
  Element: HTMLLabelElement;
}

export default class HdsFilterBarFilterGroupCheckbox extends Component<HdsFilterBarFilterGroupCheckboxSignature> {
  private _elementId = 'checkbox' + guidFor(this);

  get isChecked(): boolean {
    const { keyFilter, value } = this.args;
    if (keyFilter && Array.isArray(keyFilter.data)) {
      return keyFilter.data.some((filter) => filter.value === value);
    }
    return false;
  }

  get isHidden(): boolean {
    const { searchValue, label } = this.args;
    if (searchValue && searchValue.length > 0) {
      return !label.toLowerCase().includes(searchValue.toLowerCase());
    }
    return false;
  }

  get classNames(): string {
    const classes = [
      'hds-filter-bar__filter-group__checkbox',
      'hds-filter-bar__filter-group__selection-option',
      'hds-typography-body-200',
    ];

    if (this.isHidden) {
      classes.push(`hds-filter-bar__filter-group__selection-option--hidden`);
    }

    return classes.join(' ');
  }

  onChange = (event: Event): void => {
    const { onChange, label } = this.args;
    if (onChange && typeof onChange === 'function') {
      onChange(event, label);
    }
  };

  <template>
    <label class={{this.classNames}} ...attributes for={{this._elementId}}>
      <HdsFormCheckboxBase
        class="hds-filter-bar__filter-group__selection-option__control"
        id={{this._elementId}}
        name={{@name}}
        checked={{this.isChecked}}
        @value={{@value}}
        {{on "change" this.onChange}}
      />
      <HdsTextBody
        @tag="span"
        @size="200"
        @weight="medium"
        class="hds-filter-bar__filter-group__selection-option__text-content"
      >{{@label}}</HdsTextBody>
    </label>
  </template>
}

