export interface HdsFormKeyValueInputsDeleteRowButtonSignature {
  Args: {
    onClick?: (rowData: unknown, rowIndex: number) => void;
    onInsert?: () => void;
    onRemove?: () => void;
    returnFocusTo?: HTMLFieldSetElement;
    rowData: unknown;
    rowIndex: number;
    text?: HdsButtonSignature['Args']['text'];
  };
