              HdsRichTooltipBubble
              arrowId=this._arrowId
              popoverId=this._popoverId
              setupPrimitivePopover=PP.setupPrimitivePopover
              isOpen=PP.isOpen
            )
            isOpen=PP.isOpen
            close=PP.hidePopover
          )
        ~}}
      </div></HdsPopoverPrimitive>
  </template>
}

