            <HdsTextBody
              class="hds-stepper-indicator-step__text"
              @tag="span"
              @size="100"
              @weight="medium"
            >{{@text}}</HdsTextBody>
          {{/if}}
        </div>
      {{/if}}
    </div>
  </template>
}

