    <section
      class="hds-stepper-nav__panel"
      ...attributes
      role={{if this.isNavInteractive "tabpanel"}}
      id={{this._panelId}}
      hidden={{not this.isVisible}}
      aria-labelledby={{this.coupledStepId}}
      {{this._setUpPanel this.didInsertNode this.willDestroyNode}}
    >
      {{#if this.isVisible}}
        {{yield}}
      {{/if}}
