export default class HdsAdvancedTable<
  T = HdsAdvancedTableModel,
> extends Component<HdsAdvancedTableSignature<T>> {
  @service declare readonly hdsIntl: HdsIntlService;

  @tracked
  private _selectAllCheckbox?: HdsFormCheckboxBaseSignature['Element'] =
    undefined;
  @tracked private _isSelectAllCheckboxSelected?: boolean = undefined;
  @tracked private _tableHeight = 0;
  private _selectableRows: HdsAdvancedTableSelectableRow[] = [];
  private _isBulkSelectionChange = false;
  private _captionId = 'caption-' + guidFor(this);
  private _scrollHandler!: (event: Event) => void;
  private _dragOverHandler!: (event: DragEvent) => void;
  private _resizeObserver!: ResizeObserver;
  private _theadElement!: HTMLDivElement;
  private _scrollWrapperElement!: HTMLDivElement;

  @tracked scrollIndicatorDimensions = DEFAULT_SCROLL_DIMENSIONS;
  @tracked isStickyColumnPinned = false;
  @tracked isStickyHeaderPinned = false;
  @tracked hasPinnedFirstColumn: boolean | undefined = undefined;
  @tracked reorderedMessageText = '';
  @tracked showScrollIndicatorLeft = false;
  @tracked showScrollIndicatorRight = false;
  @tracked showScrollIndicatorTop = false;
  @tracked showScrollIndicatorBottom = false;
  @tracked stickyColumnOffset = '0px';

  // sorting properties
  @tracked currentSortBy?: string;
  @tracked currentSortOrder: HdsAdvancedTableThSortOrder =
    HdsAdvancedTableThSortOrderValues.Asc;

  // row expansion properties
  expandedRowIds = new TrackedSet<string>();

  private _setUpScrollWrapper = modifier((element: HTMLDivElement) => {
    this._scrollWrapperElement = element;

    const updateHorizontalScrollIndicators = () => {
      this.showScrollIndicatorRight = element.clientWidth < element.scrollWidth;
    };

    const updateBottomScrollIndicator = () => {
      // when hasReorderableColumns is true, the reorder handles are absolutely
      // positioned with translateY(50%), which causes them to overflow the
      // header's bottom edge by half their height, inflating scrollHeight even
      // when there is no actual scrollable content. visibility:hidden means
      // getBoundingClientRect() returns zeros at mount time, so we use
      // offsetHeight / 2 instead.
      let reorderHandleOverflow = 0;
      if (this.args.hasReorderableColumns) {
        const firstHandle = this._theadElement?.querySelector(
          '.hds-advanced-table__th-reorder-handle'
        ) as HTMLElement;
        if (firstHandle) {
          reorderHandleOverflow = firstHandle.offsetHeight / 2;
        }
      }

      this.showScrollIndicatorBottom =
        element.scrollHeight - reorderHandleOverflow - element.clientHeight > 0;
    };

    this._scrollHandler = () => {
      this._updateScrollIndicators(element);
    };

    this._dragOverHandler = (event: DragEvent) => {
      if (this.args.hasReorderableColumns !== true) {
        return;
      }

      const canScrollHorizontally = element.scrollWidth > element.clientWidth;

      if (!canScrollHorizontally) {
        return;
      }

      const firstReorderDropTarget = element.querySelector(
        '.hds-advanced-table__th-reorder-drop-target'
      );

      if (firstReorderDropTarget === null) {
        return;
      }

      const stickyColumnHeaders = element.querySelectorAll(
        '.hds-advanced-table__th--is-sticky-column'
      );
      const lastStickyColumnHeader = stickyColumnHeaders[
        stickyColumnHeaders.length - 1
      ] as HTMLDivElement | undefined;

      const leftVisibleEdge =
        lastStickyColumnHeader?.getBoundingClientRect().right ??
        firstReorderDropTarget.getBoundingClientRect().left;

      const leftScrollTrigger =
        lastStickyColumnHeader !== undefined
          ? leftVisibleEdge
          : leftVisibleEdge + REORDER_EDGE_SCROLL_TRIGGER_PX;

      const { right } = element.getBoundingClientRect();
      const rightScrollTrigger = right - REORDER_EDGE_SCROLL_TRIGGER_PX;

      if (event.clientX <= leftScrollTrigger) {
        element.scrollBy({ left: -REORDER_EDGE_SCROLL_STEP_PX });
      } else if (event.clientX >= rightScrollTrigger) {
        element.scrollBy({ left: REORDER_EDGE_SCROLL_STEP_PX });
      }
    };

    element.addEventListener('scroll', this._scrollHandler);
    element.addEventListener('dragover', this._dragOverHandler);

    const updateMeasurements = () => {
      const { isSelectable = false } = this.args;

      const newTableHeight = element.offsetHeight;

      const newDimensions = getScrollIndicatorDimensions(
        element,
        this._theadElement,
        this.hasStickyFirstColumn ? true : false,
        this.isStickyColumnPinned
      );

      const setUpdatedMeasurements = () => {
        if (this.isDestroying || this.isDestroyed) {
          return;
        }

        const isSameBottom =
          this.scrollIndicatorDimensions.bottom === newDimensions.bottom;
        const isSameHeight =
          this.scrollIndicatorDimensions.height === newDimensions.height;
        const isSameLeft =
          this.scrollIndicatorDimensions.left === newDimensions.left;
        const isSameRight =
          this.scrollIndicatorDimensions.right === newDimensions.right;

        if (
          isSameBottom &&
          isSameHeight &&
          isSameLeft &&
          isSameRight &&
          this._tableHeight === newTableHeight
        ) {
          return;
        }

        this._tableHeight = newTableHeight;
        this.scrollIndicatorDimensions = newDimensions;

        if (this.hasStickyFirstColumn) {
          this.stickyColumnOffset = getStickyColumnLeftOffset(
            this._theadElement,
            isSelectable,
            this.isStickyColumnPinned
          );
        }
      };

      requestAnimationFrameWaiter(setUpdatedMeasurements);
    };

    this._resizeObserver = new ResizeObserver((entries) => {
      entries.forEach(() => {
        updateMeasurements();
        updateHorizontalScrollIndicators();
        updateBottomScrollIndicator();
      });
    });

    this._resizeObserver.observe(element);

    updateMeasurements();

    // on render check if should show right scroll indicator
    updateHorizontalScrollIndicators();

    // on render check if should show bottom scroll indicator
    updateBottomScrollIndicator();

    return () => {
      element.removeEventListener('scroll', this._scrollHandler);
      element.removeEventListener('dragover', this._dragOverHandler);
      this._resizeObserver.disconnect();
    };
  });

  private _setUpThead = modifier((element: HTMLDivElement) => {
    this._theadElement = element;
  });

  private _syncSortArgs = modifier(() => {
    const { sortBy, sortOrder } = this.args;

    if (sortBy !== undefined) {
      this.currentSortBy = sortBy;
    }

    if (sortOrder !== undefined) {
      this.currentSortOrder = sortOrder;
