          <H.Th>Partition</H.Th>
        </H.Tr>
      </:head>
      <:body as |B|>
        {{#each
          (call (fn this.myDemoCustomSortingFunction B.sortBy B.sortOrder))
          as |cluster|
        }}
          <B.Tr>
            <B.Td>{{get cluster "peer-name"}}</B.Td>
            <B.Td>{{get cluster "status"}}</B.Td>
            <B.Td>{{get cluster "cluster-partition"}}</B.Td>
          </B.Tr>
        {{/each}}
      </:body>
    </HdsTable>
  </template>
}

